param([string]$RunDate='PLAN-DATE',[ValidateSet('PLAN','EXECUTE')][string]$ExecutionMode='PLAN')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$runner=Join-Path $PSScriptRoot 'run-experiment-1-23-core.ps1';$result=Join-Path $root 'backend\experiments\results\experiment-1-23';$runs=@(@{c='BASELINE';i='001'},@{c='REMEDIATION';i='001'},@{c='BASELINE';i='002'},@{c='REMEDIATION';i='002'},@{c='BASELINE';i='003'},@{c='REMEDIATION';i='003'});New-Item -ItemType Directory -Force -Path (Join-Path $result 'plan')|Out-Null;$failure=$null;foreach($r in $runs){try{& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $r.c -RunIndex $r.i -RunDate $RunDate -ExecutionMode $ExecutionMode;if($LASTEXITCODE){throw "core exit $LASTEXITCODE"}}catch{$failure=$_;break}};$states=@($runs|ForEach-Object{$id="RUN-$RunDate-EXP123-$($_.c)-$($_.i)";$dir=Join-Path $result "core\$id";$warm=Join-Path $root "experiment\results\SMOKE-$RunDate-EXP123-$($_.c)-$($_.i)";[ordered]@{runId=$id;started=Test-Path $dir;completed=Test-Path (Join-Path $dir 'COMPLETED');failed=Test-Path (Join-Path $dir 'EXECUTION_FAILED');warmupInvoked=Test-Path $warm;coreInvoked=Test-Path (Join-Path $dir 'execution-summary.json')}});$ledger=[ordered]@{experiment='Experiment 1-23';runDate=$RunDate;executionMode=$ExecutionMode;requestedRuns=@($runs|ForEach-Object{"$($_.c)-$($_.i)"});startedRuns=@($states|Where-Object started).Count;completedRuns=@($states|Where-Object completed).Count;failedRuns=@($states|Where-Object failed).Count;notStartedRuns=@($states|Where-Object{-not$_.started}|ForEach-Object runId);warmup=@($states|Where-Object warmupInvoked).Count;k6=0;core=@($states|Where-Object coreInvoked).Count;executionStatus=if($ExecutionMode-eq'PLAN'){'NOT_RUN'}elseif($failure){'FAILED'}elseif(@($states|Where-Object completed).Count-eq6){'COMPLETED'}else{'INCOMPLETE'};runStates=$states};$ledger|ConvertTo-Json -Depth 10|Set-Content (Join-Path $result 'plan\runner-readiness.json') -Encoding UTF8;if($failure){throw $failure};if($ExecutionMode-eq'PLAN'){'EXP123_PLAN_READY'}
